// RGB LED — three LEDs in one package.
//
// Each colour has its own PWM pin and 220 ohm resistor, so the channels mix
// independently. Run it to cycle red, green, blue and white.

void setup() {
  pinMode(9, OUTPUT);
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);
}

void loop() {
  analogWrite(9, 255); analogWrite(10, 0);   analogWrite(11, 0);   delay(400);
  analogWrite(9, 0);   analogWrite(10, 255); analogWrite(11, 0);   delay(400);
  analogWrite(9, 0);   analogWrite(10, 0);   analogWrite(11, 255); delay(400);
  analogWrite(9, 255); analogWrite(10, 255); analogWrite(11, 255); delay(400);
}
